"""Monthly 50/30/20 volatility control for historical research."""

import json
import signal
from datetime import datetime
from hashlib import sha256
from io import BytesIO
from pathlib import Path

import numpy as np
import pandas as pd
import yaml
import gzip
from pandas.tseries.holiday import (
    AbstractHolidayCalendar,
    GoodFriday,
    Holiday,
    USLaborDay,
    USMartinLutherKingJr,
    USMemorialDay,
    USPresidentsDay,
    USThanksgivingDay,
    nearest_workday,
    sunday_to_monday,
)


ROOT = Path(__file__).resolve().parent
PARAM_COMBOS_TRIED = 1
PRICE_ADJUSTMENT = "yfinance auto_adjust ETF closes rebased at warmup; ^IRX discount yields"


class EquityHolidays(AbstractHolidayCalendar):
    rules = [
        Holiday("New Year's Day", month=1, day=1, observance=sunday_to_monday),
        USMartinLutherKingJr,
        USPresidentsDay,
        GoodFriday,
        USMemorialDay,
        Holiday("Juneteenth", month=6, day=19, start_date="2022-01-01", observance=nearest_workday),
        Holiday("Independence Day", month=7, day=4, observance=nearest_workday),
        USLaborDay,
        USThanksgivingDay,
        Holiday("Christmas Day", month=12, day=25, observance=nearest_workday),
    ]


def equity_sessions(start, end):
    # Full-day closures supplement the recurring rules for the configured sample.
    closures = pd.to_datetime([
        "2007-01-02",  # Ford national day of mourning
        "2012-10-29", "2012-10-30",  # Hurricane Sandy
        "2018-12-05",  # Bush national day of mourning
        "2025-01-09",  # Carter national day of mourning
    ])
    holidays = EquityHolidays().holidays(start, end).union(closures)
    return pd.bdate_range(start, end).difference(holidays)



def load_config(config_path="config.yaml"):
    with open(config_path, "rb") as file:
        raw = file.read()
    return yaml.safe_load(raw), raw


def load_prices(settings, config_path="config.yaml"):
    data = settings.get("data") or {}
    blob = data.get("market_snapshot_gzip")
    expected_digest = data.get("market_snapshot_sha256")
    if not isinstance(blob, (bytes, bytearray)) or not expected_digest:
        raise ValueError("config.data must carry market_snapshot_gzip and market_snapshot_sha256")
    snapshot = gzip.decompress(bytes(blob))
    digest = sha256(snapshot).hexdigest()
    if digest != expected_digest:
        raise ValueError(
            f"SHA-256 mismatch for the market snapshot in {Path(config_path).name}: {digest}."
        )
    header, sep, body = snapshot.partition(b"\n")
    if not sep:
        raise ValueError("Missing cache timestamp")
    fetched_at = header.decode("utf-8").strip()
    price_timestamp = datetime.fromisoformat(fetched_at)
    input_digest = sha256(body).hexdigest()
    with BytesIO(snapshot) as source:
        source.readline()
        frame = pd.read_csv(source, index_col="date", parse_dates=["date"])
    provenance = {
        "path": Path(config_path).name,
        "key": "data.market_snapshot_gzip",
        "sha256": digest,
    }
    print(
        "Data source: yfinance auto_adjust snapshot embedded in config under data.market_snapshot_gzip "
        f"(decompressed sha256 {digest}); the script does not call yfinance or read data_cache."
    )
    print(f"Input SHA-256: {input_digest}")
    print(f"DATA_SHA256: {digest}")
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(provenance, allow_nan=False)}")
    return frame, price_timestamp


def split_closes(frame, risky_tickers, excess_ticker, start, end, sessions):
    if not frame.index.is_unique or not frame.index.is_monotonic_increasing:
        raise ValueError("Yahoo Finance close dates must be unique and sorted")
    frame = frame.loc[start:end]
    risky_closes = frame[risky_tickers]
    unexpected = risky_closes.dropna(how="all").index.difference(sessions)
    if len(unexpected):
        raise ValueError(f"ETF quotes outside the exchange calendar: {unexpected[0].date()}")
    risky_closes = risky_closes.reindex(sessions)
    invalid = ~np.isfinite(risky_closes) | (risky_closes <= 0)
    if invalid.any().any():
        first = invalid.index[invalid.any(axis=1)][0]
        tickers = ", ".join(invalid.columns[invalid.loc[first]])
        raise ValueError(f"Missing or invalid ETF close on {first.date()}: {tickers}")
    bill_quote = frame[excess_ticker].dropna()
    if (bill_quote.empty or (bill_quote.index[0] - start).days > 7
            or (end - bill_quote.index[-1]).days > 7 or not np.isfinite(bill_quote).all()):
        raise ValueError(f"Incomplete Yahoo Finance close history for {excess_ticker}")
    return risky_closes, bill_quote


def cash_proxy_returns(sessions, bill_quote, quote_lag_sessions):
    session_dates = sessions.to_series()
    # Date-only quotes get a publication buffer before the start of the return interval.
    quote_shift = 1 + quote_lag_sessions
    bill_rate = bill_quote.reindex(sessions, method="ffill").shift(quote_shift)
    bill_quote_date = bill_quote.index.to_series().reindex(sessions, method="ffill").shift(quote_shift)
    bill_quote_age = (session_dates.shift(1) - bill_quote_date).dt.days
    days = session_dates.diff().dt.days
    bill_discount = bill_rate / 100.0
    # A 13-week bill's discount quote implies a price per dollar of face value.
    bill_price = 1.0 - bill_discount * 91.0 / 360.0
    if (bill_price <= 0).any():
        raise ValueError("The ^IRX quote implied a nonpositive Treasury bill price")
    cash_returns = bill_price ** (-days / 91.0) - 1.0
    return cash_returns, bill_quote_age


def rebalance_targets(returns, base_weights, start, lag, lookback, target_vol, sessions_per_year):
    sessions = returns.index
    blend = returns @ base_weights
    volatility = blend.rolling(lookback).std() * np.sqrt(sessions_per_year)
    dates = sessions.to_series()
    fill_dates = dates.shift(-lag)
    month_ends = dates.groupby(sessions.to_period("M")).last()
    year_ends = dates.groupby(sessions.to_period("Y")).last()

    dynamic = {}
    for signal in month_ends:
        fill = fill_dates.loc[signal]
        if pd.isna(fill) or fill < start:
            continue
        sigma = volatility.loc[signal]
        if not np.isfinite(sigma):
            raise ValueError(f"Insufficient volatility history at the {signal.date()} signal")
        scale = target_vol / max(sigma, target_vol)
        dynamic[fill] = base_weights * scale
    # The fixed allocation is known before the sample starts, even without a strategy signal.
    first_fill = max(lag, sessions.searchsorted(start))
    if first_fill >= len(sessions):
        return dynamic, {}
    first_benchmark_fill = sessions[first_fill]
    benchmark = {first_benchmark_fill: base_weights}
    for signal in year_ends[year_ends > first_benchmark_fill]:
        fill = fill_dates.loc[signal]
        if pd.notna(fill):
            benchmark[fill] = base_weights
    return dynamic, benchmark


def size_position_changes(positions, cash, prior_close, target, fee_rate, cash_buffer):
    value = positions @ prior_close + cash
    target = np.asarray(target, dtype=float)
    # Each side's planned notional is at most the portfolio value at the sizing prices.
    weight_cap = 1.0 - cash_buffer - 2.0 * fee_rate
    target_weight = target.sum()
    if target_weight > weight_cap:
        target = target * (weight_cap / target_weight)
    changes = target * value / prior_close - positions
    changes[np.abs(changes) * prior_close <= 1e-12 * value] = 0.0
    changes.setflags(write=False)
    return changes


def fill_position_changes(positions, cash, close, changes, fee_rate, session):
    # Settle the fixed quantities; a shortfall invalidates the simulation.
    amounts = changes * close
    traded = np.abs(amounts).sum()
    fees = traded * fee_rate
    remaining_cash = cash - amounts.sum() - fees
    if not np.isfinite(remaining_cash):
        raise RuntimeError(f"{session.date()}: nonfinite cash after settlement")
    if remaining_cash < 0.0:
        raise RuntimeError(
            f"{session.date()}: insufficient cash for fixed fill quantities "
            f"(shortfall {-remaining_cash:.6g} starting-capital units)"
        )
    new_positions = positions + changes
    if (new_positions < 0.0).any():
        raise RuntimeError(f"{session.date()}: fixed fill quantities would create a short position")
    trades = np.count_nonzero(new_positions != positions)
    return new_positions, remaining_cash, traded, fees, trades


def simulate(prices, cash_returns, targets, fee_rate, cash_buffer):
    sessions = cash_returns.index
    columns = ["return", "turnover", "n_trades"]
    if sessions.empty:
        return pd.DataFrame(index=sessions, columns=columns)

    positions = np.zeros(prices.shape[1])
    cash = 1.0
    prior_value = cash
    prior_close = prices.shift(1).loc[sessions[0]].to_numpy()
    first_target = targets.get(sessions[0])
    pending_changes = None
    if first_target is not None:
        pending_changes = size_position_changes(positions, cash, prior_close, first_target, fee_rate, cash_buffer)

    closes = prices.loc[sessions].to_numpy()
    next_sessions = sessions.to_series().shift(-1)
    rows = []
    for session, next_session, close, cash_move in zip(sessions, next_sessions, closes, cash_returns, strict=True):
        # Existing positions and cash earn the full close-to-close move before the fill.
        daily_return = (positions @ (close - prior_close)) / prior_value + (cash / prior_value) * cash_move
        cash += cash * cash_move
        turnover = 0.0
        trades = 0
        if pending_changes is not None:
            pre_fill_value = positions @ close + cash
            positions, cash, traded, fees, trades = fill_position_changes(
                positions, cash, close, pending_changes, fee_rate, session
            )
            daily_return -= fees / prior_value
            turnover = 0.5 * traded / pre_fill_value
        rows.append((daily_return, turnover, trades))

        # After settlement, size only the next session's fill at this close.
        prior_close = close
        prior_value = positions @ close + cash
        next_target = targets.get(next_session)
        pending_changes = None
        if next_target is not None:
            pending_changes = size_position_changes(positions, cash, close, next_target, fee_rate, cash_buffer)

    return pd.DataFrame(rows, index=sessions, columns=columns)


def metrics(daily_results, cash_returns, sessions_per_year):
    daily = daily_results["return"].to_numpy()
    excess = daily - cash_returns.loc[daily_results.index].to_numpy()
    cumulative_growth = np.r_[1.0, np.cumprod(1.0 + daily)]
    annual_factor = sessions_per_year / len(daily)
    vol_scale = np.sqrt(sessions_per_year)
    enough_returns = len(daily) > 1
    std = daily.std(ddof=1) if enough_returns and np.ptp(daily) > 0 else 0.0
    excess_std = excess.std(ddof=1) if enough_returns and np.ptp(excess) > 0 else 0.0
    return {
        "cagr": float(cumulative_growth[-1] ** annual_factor - 1.0),
        "ann_vol": float(std * vol_scale) if enough_returns else None,
        "sharpe": float(daily.mean() / std * vol_scale) if std else None,
        "sharpe_excess": float(excess.mean() / excess_std * vol_scale) if excess_std > 0 else None,
        "max_drawdown": float((cumulative_growth / np.maximum.accumulate(cumulative_growth) - 1.0).min()),
        "total_return": float(cumulative_growth[-1] - 1.0),
        "turnover": float(daily_results["turnover"].sum() * annual_factor),
        "n_trades": int(daily_results["n_trades"].sum()),
    }


def main():
    config, _ = load_config(str(ROOT / "config.yaml"))
    date_keys = ("warmup_start", "start", "oos_start", "end")
    warmup, start, split, end = (pd.Timestamp(config["dates"][key]) for key in date_keys)
    universe = config["universe"]
    risky_tickers = list(universe)
    base_weights = pd.Series(universe, dtype=float)
    excess_ticker = config["excess_sharpe_ticker"]
    quote_lag = config["cash_quote_lag_sessions"]
    lag = config["execution_lag_sessions"]
    lookback = config["lookback_sessions"]
    target_vol = config["target_annual_vol"]
    sessions_per_year = config["sessions_per_year"]
    cost, slippage = config["cost_bps"], config["slippage_bps"]
    fee_rate = (cost + slippage) / 10_000.0
    cash_buffer = config["cash_buffer_bps"] / 10_000.0
    if not warmup < start < split < end:
        raise ValueError("Expected warmup_start < start < oos_start < end")
    if (not np.isfinite(base_weights).all() or (base_weights < 0).any()
            or not np.isclose(base_weights.sum(), 1.0)):
        raise ValueError("Risky-asset base weights must be long-only and sum to one")
    base_weights /= base_weights.sum()
    if type(lag) is not int or lag < 1:
        raise ValueError("Execution lag must be at least one whole trading session")
    if lookback < 2 or not 0 < target_vol < np.inf or sessions_per_year <= 0:
        raise ValueError("Invalid timing or volatility parameters")
    if excess_ticker != "^IRX":
        raise ValueError("The excess-return calculation requires the ^IRX bill discount quote")
    if type(quote_lag) is not int or quote_lag < 1:
        raise ValueError("Cash quotes require at least one session of publication buffer")
    if cost < 0 or slippage < 0 or not 0 <= fee_rate < 1:
        raise ValueError("Invalid fee or slippage assumptions")
    if not 0 < cash_buffer < 1.0 - 2.0 * fee_rate:
        raise ValueError("Invalid cash buffer for the fee assumptions")

    sessions = equity_sessions(warmup, end)
    closes, price_timestamp = load_prices(config, str(ROOT / "config.yaml"))
    adjusted_closes, bill_quote = split_closes(closes, risky_tickers, excess_ticker, warmup, end, sessions)
    # A later split or distribution can rescale all earlier adjusted closes. A fixed
    # warmup anchor cancels that scale from the simulated prices and share units.
    prices = adjusted_closes / adjusted_closes.iloc[0]
    returns = prices.pct_change(fill_method=None)
    cash_returns, bill_quote_age = cash_proxy_returns(sessions, bill_quote, quote_lag)
    dynamic, benchmark = rebalance_targets(returns, base_weights, start, lag, lookback, target_vol, sessions_per_year)

    evaluation = sessions[(sessions >= start) & (sessions <= end)]
    masks = {"is": evaluation < split, "oos": evaluation >= split, "full": slice(None)}
    if not masks["is"].any() or not masks["oos"].any():
        raise ValueError("Each evaluation period must contain at least one session")
    cash_returns = cash_returns.loc[evaluation]
    if not (np.isfinite(returns.loc[evaluation].to_numpy()).all()
            and np.isfinite(cash_returns).all() and (cash_returns > -1).all()):
        raise ValueError("Incomplete return inputs inside the evaluation dates")
    dynamic_results = simulate(prices, cash_returns, dynamic, fee_rate, cash_buffer)
    benchmark_results = simulate(prices, cash_returns, benchmark, fee_rate, cash_buffer)

    dynamic_periods = {
        name: metrics(dynamic_results.loc[mask], cash_returns, sessions_per_year) for name, mask in masks.items()
    }
    benchmark_periods = {
        name: metrics(benchmark_results.loc[mask], cash_returns, sessions_per_year) for name, mask in masks.items()
    }
    weight_label = "/".join(f"{weight * 100:g}" for weight in base_weights)
    benchmark_name = f"Annual fixed-weight {'/'.join(risky_tickers)} {weight_label}"
    result = {
        "strategy": config["strategy"],
        "data_range": {"start": evaluation[0].date().isoformat(), "end": evaluation[-1].date().isoformat()},
        **dynamic_periods,
        "benchmark": {"name": benchmark_name, **benchmark_periods["full"], **benchmark_periods},
    }
    print(f"DATA_FETCHED_AT: {price_timestamp.isoformat()}")
    print(f"PRICE_ADJUSTMENT: yfinance auto_adjust ETF closes rebased at warmup; {excess_ticker} discount yields")
    print(f"PARAM_COMBOS_TRIED: {PARAM_COMBOS_TRIED}")
    print(f"IRX_MAX_QUOTE_AGE_DAYS: {int(bill_quote_age.loc[evaluation].max())}")
    print(f"Benchmark | {benchmark_name}")
    rows = {
        **{f"Strategy {k.upper()}": v for k, v in dynamic_periods.items()},
        **{f"Benchmark {k.upper()}": v for k, v in benchmark_periods.items()},
    }
    print(pd.DataFrame.from_dict(rows, orient="index").to_string(float_format=lambda value: f"{value:.6f}"))
    print("RESULTS_JSON: " + json.dumps(result, allow_nan=False))


if __name__ == "__main__":
    signal.alarm(9 * 60)
    main()
